// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IWhitelist {
    function isWhitelisted(address account) external view returns (bool);
}

error NotWhitelisted(address account);

contract MinimalERC20 {
    string public name = "MinimalERC20";
    string public symbol = "MERC";
    uint8 public decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    address public immutable whitelistAddress;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(address _whitelistAddress) {
        whitelistAddress = _whitelistAddress;
    }

    function getWhitelistAddress() public view returns (address) {
        return whitelistAddress;
    }

    function _checkWhitelist(address account) internal view {
        if (!IWhitelist(whitelistAddress).isWhitelisted(account)) {
            revert NotWhitelisted(account);
        }
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _checkWhitelist(msg.sender);
        _checkWhitelist(to);
        require(balanceOf[msg.sender] >= value, "Insufficient balance");
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        emit Transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        _checkWhitelist(from);
        _checkWhitelist(to);
        require(balanceOf[from] >= value, "Insufficient balance");
        if (allowance[from][msg.sender] != type(uint256).max) {
            require(allowance[from][msg.sender] >= value, "Insufficient allowance");
            allowance[from][msg.sender] -= value;
        }
        balanceOf[from] -= value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function mint(address to, uint256 value) external {
        totalSupply += value;
        balanceOf[to] += value;
        emit Transfer(address(0), to, value);
    }
}
