import { useState, useEffect, useCallback, useRef } from 'react';

interface UseChainHeadResult {
  blockNumber: number | null;
  loading: boolean;
  error: string | null;
}

export function useChainHead(rpcUrl: string): UseChainHeadResult {
  const [blockNumber, setBlockNumber] = useState<number | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const isMountedRef = useRef<boolean>(true);
  const abortControllerRef = useRef<AbortController | null>(null);

  const fetchBlockNumber = useCallback(async () => {
    if (!isMountedRef.current) return;

    // Cancel previous request if any
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      const response = await fetch(rpcUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          jsonrpc: '2.0',
          id: 1,
          method: 'eth_blockNumber',
          params: [],
        }),
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();

      if (!isMountedRef.current) return;

      if (data.error) {
        setError(data.error.message || 'RPC error');
        setBlockNumber(null);
      } else if (typeof data.result === 'string') {
        const parsed = parseInt(data.result, 16);
        if (isNaN(parsed)) {
          throw new Error('Invalid block number format');
        }
        setBlockNumber(parsed);
        setError(null);
      } else {
        throw new Error('Unexpected response format');
      }
    } catch (err: unknown) {
      if (!isMountedRef.current) return;

      if (err instanceof DOMException && err.name === 'AbortError') {
        // Request was aborted, ignore
        return;
      }

      const message = err instanceof Error ? err.message : 'Unknown error';
      setError(message);
      setBlockNumber(null);
    } finally {
      if (isMountedRef.current) {
        setLoading(false);
      }
    }
  }, [rpcUrl]);

  useEffect(() => {
    isMountedRef.current = true;
    setLoading(true);
    setError(null);

    // Initial fetch
    fetchBlockNumber();

    // Set up interval
    const intervalId = setInterval(() => {
      if (isMountedRef.current) {
        fetchBlockNumber();
      }
    }, 5000);

    return () => {
      isMountedRef.current = false;
      clearInterval(intervalId);
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
        abortControllerRef.current = null;
      }
    };
  }, [fetchBlockNumber]);

  return { blockNumber, loading, error };
}
